    background-color: var(--color-background);
    color: var(--color-text-primary);
    line-height: 1.6;
}

/* Header */
.header {
    background-color: var(--color-surface);
    border-bottom: 1px solid var(--color-border);
    box-shadow: var(--shadow-sm);
    position: sticky;
    top: 0;
    z-index: 10;
}

.header-content {
    max-width: 1200px;
    margin: 0 auto;
    padding: var(--spacing-lg);
}

.header h1 {
    font-size: 1.875rem;
    font-weight: 700;
    color: var(--color-text-primary);
}

/* Main Content */
.app-container {
    display: flex;
    flex-direction: column;
    min-height: 100vh;
}

.main-content {
    flex: 1;
    max-width: 1200px;
    width: 100%;
    margin: 0 auto;
    padding: var(--spacing-lg);
    display: flex;
    align-items: center;
    justify-content: center;
}

/* Image Card */
.image-card {
    background-color: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    overflow: hidden;
    box-shadow: var(--shadow-md);
    width: 100%;
    max-width: 500px;
    transition: box-shadow var(--transition-normal);
}

.image-card:hover {
    box-shadow: var(--shadow-lg);
}

.image-container {
    width: 100%;
    height: 300px;
    overflow: hidden;
    background-color: var(--color-background);
}

.preview-image {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
}

.image-info {
    padding: var(--spacing-md);
    border-bottom: 1px solid var(--color-border);
}

.image-info h2 {
    font-size: 1.25rem;
    font-weight: 600;
    margin-bottom: var(--spacing-xs);
    color: var(--color-text-primary);
}

.image-meta {
    font-size: 0.875rem;
    color: var(--color-text-secondary);
}

.image-actions {
    display: flex;
    gap: var(--spacing-sm);
    padding: var(--spacing-md);
    background-color: var(--color-background);
}

